for i,l in enumerate(lines,1):
 if re.match(r'\w|[A-Z].*\{', l) and ('QuickTimeVideo::' in l or 'isQTimeType' in l): print(i,l)
# grep DataBuf / readOrThrow etc around likely dangerous
for pat in ['DataBuf','readOrThrow','read(.*data','io_->read','toUint','getULong','alloc','new','std::string','substr','size_','tagDecoder','decodeBlock']:
 print('---',pat)
 for i,l in enumerate(lines,1):
  if re.search(pat,l): print(i,l[:180])

